import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate, Easing } from '../remotionShim';
import { evolvePath } from "@remotion/paths";

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type SocialStatsPopProps = Record<string, any>;

// Path for a smooth, imperfect hand-drawn ellipse covering a 350x120 area
const HAND_DRAWN_ELLIPSE = "M 175,15 C 280,10 330,40 330,60 C 330,85 280,110 175,110 C 70,110 20,85 20,60 C 20,35 80,12 190,18";

const SocialStatsPop: React.FC<SocialStatsPopProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 2,
  highlightColor = "#10b981",
  textColor = "#ffffff",
  labelColor = "#8b949e",
  metrics = [
    { label: "Views", value: "1.2M", offsetX: -0.25, offsetY: -0.28, highlighted: true },
    { label: "Likes", value: "245K", offsetX: 0.22, offsetY: -0.15, highlighted: false },
    { label: "Comments", value: "18K", offsetX: -0.18, offsetY: 0.08, highlighted: false },
    { label: "Shares", value: "5K", offsetX: 0.28, offsetY: 0.22, highlighted: true },
    { label: "Follows", value: "+12K", offsetX: -0.05, offsetY: 0.35, highlighted: false },
  ]
}) => {
  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation triggers
  const exitStartFrame = (durationInSeconds * fps) - 15;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter, sans-serif" }}>
      {metrics.map((metric, index) => {
        // Entrance: stagger fast pops
        const entranceStagger = index * 2;
        const entranceProgress = spring({
          frame: frame - entranceStagger,
          fps,
          config: { damping: 12, stiffness: 180 } // Bouncy modern pop
        });

        // Exit: stagger scale downs
        const exitProgress = spring({
          frame: frame - exitStartFrame + index * 1.5,
          fps,
          config: { damping: 15, stiffness: 200 }
        });

        const currentScale = entranceProgress * (1 - exitProgress);
        const currentOpacity =
          interpolate(frame - entranceStagger, [0, 4], [0, 1], { extrapolateRight: "clamp" }) *
          interpolate(exitProgress, [0, 0.8], [1, 0], { extrapolateRight: "clamp" });

        // Highlight Circle: draw cleanly and hold
        const circleDrawFrame = 20 + index * 2;
        const circleProgress = interpolate(
          frame - circleDrawFrame,
          [0, 12],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.out(Easing.cubic) }
        );
        const evolution = evolvePath(circleProgress, HAND_DRAWN_ELLIPSE);

        // Positioning: responsive offsets from screen center
        const cx = width * 0.5 + width * metric.offsetX;
        const cy = height * 0.5 + height * metric.offsetY;
        const dynamicRotation = metric.offsetX * 15; // Adds an organic scattered feel

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: cx - 175,
              top: cy - 60,
              width: 350,
              height: 120,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              transform: `scale(${currentScale}) rotate(${dynamicRotation}deg)`,
              opacity: currentOpacity,
              transition: "none",
            }}
          >
            <div style={{ fontSize: 64, fontWeight: 700, color: textColor, lineHeight: 1 }}>
              {metric.value}
            </div>
            <div style={{ fontSize: 24, fontWeight: 600, color: labelColor, textTransform: "uppercase", letterSpacing: "2px", marginTop: 4 }}>
              {metric.label}
            </div>

            {metric.highlighted && (
              <svg
                width={350}
                height={120}
                style={{ position: "absolute", top: 0, left: 0, overflow: "visible", transition: "none" }}
              >
                <path
                  d={HAND_DRAWN_ELLIPSE}
                  stroke={highlightColor}
                  strokeWidth={6}
                  fill="none"
                  strokeDasharray={evolution.strokeDasharray}
                  strokeDashoffset={evolution.strokeDashoffset}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  style={{ transition: "none" }}
                />
              </svg>
            )}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default SocialStatsPop;